#!/usr/bin/env zx
import { accessSync, constants, realpathSync, statSync } from 'node:fs';
import { basename, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

// Native SDK names from the normal CMake installation. The host runs cjc;
// the target supplies std and the program's runtime. Neither selects the other.
const platforms = Object.freeze({
  linux_x86_64_cjnative: { exe: '', shared: '.so' },
  linux_aarch64_cjnative: { exe: '', shared: '.so' },
  darwin_x86_64_cjnative: { exe: '', shared: '.dylib' },
  darwin_aarch64_cjnative: { exe: '', shared: '.dylib' },
  windows_x86_64_cjnative: { exe: '.exe', shared: '.dll' },
});
function platform(tuple) {
  if (!Object.hasOwn(platforms, tuple)) throw Error(`unsupported language runtime tuple: ${tuple}`);
  return { tuple, ...platforms[tuple] };
}
function nativeTuple() {
  const os = { linux: 'linux', darwin: 'darwin', win32: 'windows' }[process.platform];
  const arch = { x64: 'x86_64', arm64: 'aarch64' }[process.arch];
  return `${os}_${arch}_cjnative`;
}
function requireFile(path, mode = constants.R_OK) {
  accessSync(path, mode);
  if (!statSync(path).isFile()) throw Error(`language input is not a file: ${path}`);
}
function checkDirectoryTuple(directory, tuple) {
  // A normal installed tuple directory must agree with its explicit selection.
  // Build-tree and compiler-private directories have no tuple in their name.
  const name = basename(directory);
  if (name.endsWith('_cjnative') && name !== tuple) throw Error(`runtime directory tuple mismatch: ${name} != ${tuple}`);
}
export function languageInputs(env = process.env) {
  const required = name => {
    if (!env[name]) throw Error(`set ${name}`);
    return realpathSync(env[name]);
  };
  const sdk = required('GC_UNIT_LANGUAGE_SDK');
  const host = required('GC_UNIT_CJC_RUNTIME_LIB_DIR');
  const target = required('GCV2_RUNTIME_LIB_DIR');
  const compilerPlatform = platform(env.GC_UNIT_CJC_RUNTIME_TUPLE || nativeTuple());
  const targetPlatform = platform(env.GC_UNIT_RUNTIME_TUPLE || compilerPlatform.tuple);
  checkDirectoryTuple(host, compilerPlatform.tuple);
  checkDirectoryTuple(target, targetPlatform.tuple);
  const cjc = join(sdk, `bin/cjc${compilerPlatform.exe}`);
  requireFile(cjc, constants.X_OK);
  if (env.CJC && realpathSync(env.CJC) !== realpathSync(cjc)) throw Error(`CJC conflicts with ${cjc}`);
  const std = join(sdk, 'lib', targetPlatform.tuple, 'libcangjie-std-core.a');
  const runtime = `libcangjie-runtime${targetPlatform.shared}`, bounds = `libboundscheck${targetPlatform.shared}`;
  for (const path of [std, join(host, `libcangjie-runtime${compilerPlatform.shared}`),
    join(target, runtime), join(target, bounds)]) requireFile(path);
  return { sdk, cjc, compiler_host_dir: host, runtime_lib_dir: target,
    compiler_host_tuple: compilerPlatform.tuple, runtime_tuple: targetPlatform.tuple,
    std_core: std, sdk_runtime_dir: join(sdk, 'runtime/lib', targetPlatform.tuple),
    runtime_library: runtime, boundscheck_library: bounds };
}
const scriptIndex = process.argv.findIndex((arg, i) => i > 0 && resolve(arg) === fileURLToPath(import.meta.url));
if (scriptIndex >= 0) {
  try {
    const args = process.argv.slice(scriptIndex + 1), inputs = languageInputs();
    if (!args.length) console.log(JSON.stringify(inputs));
    else if (args.length === 1 && args[0] === '--shell') {
      const quote = value => `'${value.replaceAll("'", "'\\''")}'`;
      for (const [name, value] of Object.entries({ GC_UNIT_LANGUAGE_SDK: inputs.sdk,
        GC_UNIT_CJC_RUNTIME_LIB_DIR: inputs.compiler_host_dir, GCV2_RUNTIME_LIB_DIR: inputs.runtime_lib_dir,
        GC_UNIT_RUNTIME_TUPLE: inputs.runtime_tuple, GC_UNIT_CJC_RUNTIME_TUPLE: inputs.compiler_host_tuple,
        GC_UNIT_SDK_RUNTIME_DIR: inputs.sdk_runtime_dir, CJC_BIN: inputs.cjc })) console.log(`export ${name}=${quote(value)}`);
    } else throw Error('usage: language_toolchain.mjs [--shell]');
  }
  catch (error) { console.error(`LANGUAGE_INPUT_NOT_RUN: ${error.message}`); process.exitCode = 2; }
}

